/*
 * Inlines the guide's Markdown fragments (`guide/*.md`) into
 * `src/guide-data.generated.ts`, so `renderGuide` never reads a file: not in
 * the tests, the CLI bundle or fortrip-ai. `build` and `test` run it first;
 * the generated file is committed.
 */
import { readdir, readFile, writeFile } from "node:fs/promises";

const guide = new URL("../guide/", import.meta.url);
const target = new URL("../src/guide-data.generated.ts", import.meta.url);

const names = (await readdir(guide)).filter((name) => name.endsWith(".md"));
const fragments: Record<string, string> = {};
for (const name of names.sort()) {
  fragments[name.slice(0, -".md".length)] = await readFile(
    new URL(name, guide),
    "utf8",
  );
}

await writeFile(
  target,
  `// Generated by scripts/embed-guide.ts from guide/*.md. Edit those, not this.

/** The guide's Markdown fragments, by file name without \`.md\`. */
export const FRAGMENTS: Record<string, string> = ${JSON.stringify(fragments, null, 2)};
`,
);
